head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

//----W-Craft WebSquare 변환 확인: include----//

// 	//----W-Craft WebSquare 변환 확인: include----//

// 	//----W-Craft WebSquare 변환 확인: include----//

// 	//----W-Craft WebSquare 변환 확인: include----//

// 	//----W-Craft WebSquare 변환 확인: include----//
scwin.vScrenID = "ULDFIS00100_P2.gfm";

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
    // 업종 조회
    scwin.search();
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.btn_close_onclick = function() {
    // 닫기버튼 클릭
    scwin.closeFrame();
};

scwin.btn_confirm_onclick = function() {
    // 확인버튼 클릭
    scwin.setParam();
};

scwin.trv_stdInd_ondblclick = function() {
    scwin.setParam();
};

///////// 4. 서브미션 콜백 영역 /////////
scwin.sbm_stdIndList_submitdone = function (e) {
    dlt_stdIndListRes.setJSON(e.responseJSON.body);

    // trv_stdInd.setNodeSet("data:dlt_stdIndListRes", 
    //     [{label: "stdIndNm", value: "stdIndCd", parent: "lv"}]
    // );

    // 데이터셋 OnLoadCompleted
    if (dlt_stdIndListRes.errorMsg) {
        alert(dlt_stdIndListRes.errorMsg);
    }
};

scwin.sbm_stdIndList_submiterror = function (e) {
    $c.win.alert(dlt_stdIndListRes);
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 *  데이터셋 초기화.
 */
scwin.initDs = function() {
    dlt_stdIndListRes.removeAll();
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {
    return true;
};

/**
 * 업종목록 조회
 */
scwin.search = function() {
    //데이터셋 초기화
    scwin.initDs();

    // 조회조건 필수 체크.
    if (!scwin.chkValid()) {
        return;
    }

    const sbmOptions = {
        id : "sbm_stdIndList",
        action : "/api/listing/common/std-ind/select-list",
        method : "get",
        target : "dlt_stdIndListRes",
        submitDoneHandler : scwin.sbm_stdIndList_submitdone,
        submitErrorHandler : scwin.sbm_stdIndList_submiterror,
        isProcessMsg : false
    };
    $c.sbm.executeDynamic(sbmOptions);
};

/**
 * 선택된 값을 오프너에 전달한다.
 */
scwin.setParam = function(v_Currow) {
    if (v_Currow === undefined) {
        v_Currow = dlt_stdIndListRes.getRowPosition();
    }
    // var arrPar = new Array();
    // arrPar[0] = {
    //     STD_IND_CD: dlt_stdIndListRes.getCellData(v_Currow, "STD_IND_CD"), //업종코드	
    //     STD_IND_NM: dlt_stdIndListRes.getCellData(v_Currow, "STD_IND_NM") //업종명
    // };

    //----W-Craft WebSquare 변환 확인: fn_SetParStdIndCd----//
    // opener.fn_SetParStdIndCd(arrPar);
    // scwin.fn_CloseFrame();

    const res = dlt_stdIndListRes.getRowJSON(v_Currow);
    $c.win.closePopup(res);
};

/**
 * close frame
 */
scwin.closeFrame = async function() {
    $c.win.closePopup();
};
